{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello रंजन जी आपको tempered glass making machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हम्म बोलिए।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "चलिए अब automation grade के बारे में बात कर लेते हैं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको semi-automatic चाहिए या automatic?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "तो"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "इसके बारे में जानकारी हमको नहीं आप हमको बताएं।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "इससे नहीं automatic क्या होता है और automatic क्या होता है?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "semi automatic में कुछ काम आपको खुद करने होंगे जबकि automatic machine सारा काम अपने आप करती है।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "अब बताइए आप क्या prefer करेंगे?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "मुझे दोनों के बारे में पहले बताइए।"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "इसमें automatic में जिस type किस type का काम करना होगा?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "means बताइए तो खोल के हमको।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "semi-automatic में आपको glass slot करने और finishing जैसे कुछ steps manually करने होंगे।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "बाकी काम machine करेगी।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब बताइए आपको कौन सा चाहिए?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "semi automatic ही बताइए।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "अब बताइए production capacity में आप क्या prefer करेंगे?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "production में नहीं समझ नहीं पा रहा मैं क्या बोल रहा हूं।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "production capacity का मतलब है कि एक दिन में machine कितने glass बना सकती है इसके बारे में आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पर भेज दूंगी जिनसे आप details और price..."
    }
  ]
}
